INSERT INTO games (title, english_title, developer, publisher, genre, platforms, release_date, status, description, hype_score, rating) VALUES
('黑神话：悟空', 'Black Myth: Wukong', '游戏科学', '游戏科学', ARRAY['动作RPG','神话','魂系'], ARRAY['PC','PS5','Xbox'], '2024-08-20', 'released', '国产3A开山之作。全球销量超2000万份，TGA年度最佳动作游戏。', 98, 9.5),
('影之刃零', 'Phantom Blade Zero', '灵游坊', '灵游坊', ARRAY['动作RPG','武侠','暗黑'], ARRAY['PC','PS5'], '2026-09-09', 'announced', '暗黑武侠功夫朋克。主角生命仅剩66天，全人类手工制作拒绝AI。主线20-30小时，愿望单破百万。', 95, NULL),
('湮灭之潮', 'Tides of Annihilation', '蛇夫座·日蚀边缘', '腾讯', ARRAY['动作ACT','奇幻','亚瑟王'], ARRAY['PC','PS5','Xbox'], NULL, 'in-dev', '腾讯旗下100人成都团队。亚瑟王传说×伦敦废墟，鬼泣式高速ACT，骑士协同战斗系统，30+Boss战。', 88, NULL),
('归唐', 'Blood Message', '网易雷火·临安24', '网易', ARRAY['动作冒险','历史','叙事'], ARRAY['PC','主机'], NULL, 'in-dev', '网易首款自研买断制3A单机。安史之乱后敦煌信使的归唐之路，写实搏杀，叙事动作冒险。UE5打造。', 86, NULL),
('黑神话：钟馗', 'Black Myth: Zhong Kui', '游戏科学', '游戏科学', ARRAY['动作RPG','神话','捉鬼'], ARRAY['PC','PS5'], '2027', 'in-dev', '游戏科学第二款3A独立作品。以钟馗为主角，UE5打造全新捉鬼宇宙。团队已扩至165人。', 92, NULL),
('望月', NULL, '月灵工作室', '独立', ARRAY['开放世界','魂系','都市'], ARRAY['PC'], '2026年Q4', 'in-dev', '老广都市风开放世界。月灵协战+五行克制+骇入系统融合玩法，6月广州线下试玩。', 78, NULL),
('燕云十六声', 'Where Winds Meet', '网易', '网易', ARRAY['开放世界','武侠','历史'], ARRAY['PC','移动端'], '2026', 'in-dev', '网易开放世界武侠巨制。五代十国历史背景，单人模式×多人模式双线并行。', 72, NULL),
('锦衣卫', NULL, '成都离忧', '独立', ARRAY['动作RPG','武侠','历史'], ARRAY['PC'], NULL, 'announced', '国产武侠动作新作。以明朝锦衣卫为背景，主打写实搏杀与历史沉浸感。', 65, NULL);
INSERT INTO leaks (title, summary, content, source, credibility, game_name, status, published_at, view_count) VALUES
('网易《归唐》SGF首曝实机，开发团队超200人', '沉寂一年后归唐突然发7秒动态+李白诗句预热，确认6月6日SGF全球首秀。', '归唐在沉寂近一年后突然官宣参加2026夏日游戏节。6月1日发布了一段7秒场景动态视频，配文"长风几万里"。SGF主持人Geoff Keighley亲自转发预热。', '内部消息+官方确认', 'confirmed', '归唐', 'published', '2026-06-01', 12800),
('《湮灭之潮》今夏成都线下试玩，全员开放报名', '腾讯SPARK发布会上制作人付坤确认，湮灭之潮将于今夏在成都举办首次线下试玩会。', '试玩信息：时间2026年夏季，地点成都，面向所有玩家开放报名。团队约100人，含世嘉育碧卡普空资深开发者。', '腾讯SPARK 2026发布会', 'confirmed', '湮灭之潮', 'published', '2026-05-28', 9500),
('《影之刃零》定价传闻引热议，官方辟谣358元', '网传影之刃零标准版358元，制作人梁其伟辟谣称太贵。全人类手工拒绝AI制作。', '灵游坊工作室澄清网络流传的实体版预售和定价均为不实信息。正式发售日2026年9月9日。', '电商平台+官方辟谣', 'rumor', '影之刃零', 'published', '2026-05-14', 7600),
('《黑神话：钟馗》首支实机视频发布', '游戏科学在马年新春突然发布6分钟钟馗实机片段。冯骥澄清：没操作没战斗没玩法没钟馗，仅为节日祝福。', '2026年2月10日冯骥发布实机短片。不是悟空DLC，是全新独立作品。团队已扩至165人。', '游戏科学官方', 'confirmed', '黑神话：钟馗', 'published', '2026-02-10', 15200),
('腾讯蛇夫座第二项目曝光：现代军事题材战术射击', '继湮灭之潮后，腾讯蛇夫座的第二款3A项目浮出水面，据悉为现代军事战术射击题材。', '通过招聘信息交叉验证，蛇夫座正在招聘具有军事战术射击经验的开发者。', '招聘信息', 'likely', '蛇夫座新作', 'published', '2026-05-31', 4200),
('游戏科学第三项目代号山海：开放世界探索方向', '继黑神话悟空和钟馗之后，游戏科学第三个3A项目曝光。以西游记+山海经为世界观基底。', '多方招聘信息显示游戏科学正在招募开放世界相关人才。代号山海，早期预研阶段。', '招聘信息', 'likely', '黑神话系列', 'published', '2026-05-29', 6800);
INSERT INTO articles (title, content, category, required_tier, tags, status) VALUES
('影之刃零深度前瞻：暗黑武侠的最后冲刺', '影之刃零不是简单的国产魂系。它是一封写给香港功夫片的情书。主角灵魂雨仅剩66天生命，每一次战斗都是在与时间赛跑。制作人梁其伟公开承诺绝不用AI图形技术。正式发售：2026年9月9日，平台PC/PS5，主线20-30小时。', 'preview', 'silver', ARRAY['影之刃零','灵游坊','暗黑武侠'], 'published'),
('归唐：网易憋了一年的牌，终于要亮了', '网易做买断制单机3A，这是个足以让整个行业侧目的事情。归唐讲的是安史之乱后，河西走廊被吐蕃占了六十多年。公元848年张议潮在沙州起义，派出十队信使穿过三千里敌占区去长安报信。你要扮演其中一队信使里的无名小卒。6月6日SGF全球首秀。', 'analysis', 'free', ARRAY['归唐','网易','安史之乱','敦煌'], 'published'),
('湮灭之潮：中国人做亚瑟王游戏，老外先疯了', '100人成都团队，腾讯控股95%，做了一款纯正亚瑟王题材的3A单机。战斗系统不是魂like更接近鬼泣：高速连招、骑士协同、弹反处决爆气。10多种圆桌骑士可以收集。30+场Boss战，主线超30小时。', 'analysis', 'free', ARRAY['湮灭之潮','腾讯','蛇夫座','亚瑟王'], 'published'),
('黑神话：悟空一周年——国产3A的破晓与未知', '一年过去，黑神话悟空依然是国产3A的标杆。全球2000万+销量，TGA年度最佳动作游戏。从悟空到钟馗，游戏科学没有急着做DLC，选择了更难的路。官方明确表示西游不会到此为止。从黑神话到影之刃零，从归唐到湮灭之潮，国产3A不再是一个孤例。', 'review', 'free', ARRAY['黑神话悟空','游戏科学','钟馗','国产3A'], 'published');
